// Payslips table for one payroll run. Money columns use the shared
// moneyColumn factory (tabular nums); status renders as a tone-mapped pill;
// trailing actions are "View PDF" (only once the run is POSTED — the PDFs
// are generated by the post) plus PayslipRowActions.
//
// The run-detail composite nests the money under `row.salary` and returns
// its own employee shape (not `EmployeeSummary`), so both are read through
// selectors here rather than by dataIndex.

import { useState } from 'react';
import {
  App as AntdApp,
  Button,
  Empty,
  Space,
  Table,
  Tooltip,
  type TableColumnsType,
} from 'antd';
import { FileText } from 'lucide-react';
import { getErrorMessage, hasCode, isApiError } from '@/lib';
import { MoneyCell, StatusPill, employeeColumn, moneyColumn } from '@/components';
import type { EmployeeRef } from '@/components';
import {
  PAYSLIP_STATUS_LABEL,
  PAYSLIP_STATUS_TONE,
  payslipsApi,
  type PayslipWithEmployee,
  type PayrollRunDto,
  type PayslipStatus,
} from '@/payroll';
import { PayslipRowActions } from './PayslipRowActions';

export type RunPayslipsTableProps = {
  runId: number;
  payslips: PayslipWithEmployee[];
  loading: boolean;
  runStatus: PayrollRunDto['status'];
  onRefresh: () => void;
  /** 0-based current page (matches Spring). */
  page: number;
  pageSize: number;
  totalElements: number;
  /** AntD pagination is 1-based; the route handles the offset. */
  onPageChange: (page: number, pageSize: number) => void;
  /** Row click opens the payslip detail drawer in the parent. */
  onOpenDetail?: (payslipId: number) => void;
  /** Employee-cell click opens the shared attendance day drawer. */
  onOpenAttendance?: (row: PayslipWithEmployee) => void;
};

/** The slip's employee block in the shape the shared person cell wants. */
function toEmployeeRef(row: PayslipWithEmployee): EmployeeRef | null {
  const e = row.employee;
  if (!e) return null;
  return {
    id: e.employeeId,
    fullName: e.fullName,
    employeeCode: e.employeeCode,
    designationTitle: e.designation,
    departmentName: e.department,
    profilePictureUrl: e.profilePictureUrl,
  };
}

export function RunPayslipsTable({
  runId,
  payslips,
  loading,
  runStatus,
  onRefresh,
  page,
  pageSize,
  totalElements,
  onPageChange,
  onOpenDetail,
  onOpenAttendance,
}: RunPayslipsTableProps) {
  const { message } = AntdApp.useApp();
  const [pdfPendingId, setPdfPendingId] = useState<number | null>(null);
  const canViewPdf = runStatus === 'POSTED';

  // Fresh signed URL (10-min expiry) on every click — never cached. Access
  // rules are the server's; a 404 here means the PDF doesn't exist yet.
  async function viewPdf(payslipId: number) {
    setPdfPendingId(payslipId);
    try {
      const { url } = await payslipsApi.pdfUrl(payslipId);
      window.open(url, '_blank', 'noopener');
    } catch (e) {
      if (hasCode(e, 'PAYSLIP_NOT_FOUND')) {
        message.info('Payslip PDF is generated when the run is posted');
      } else {
        if (isApiError(e)) {
          console.error('Payslip PDF URL failed', { correlationId: e.correlationId });
        }
        message.error(getErrorMessage(e));
      }
    } finally {
      setPdfPendingId(null);
    }
  }

  const columns: TableColumnsType<PayslipWithEmployee> = [
    {
      ...employeeColumn<PayslipWithEmployee>({
        employee: toEmployeeRef,
      }),
      // No /people/{id} link here: clicking the employee cell opens the
      // shared attendance day drawer (same as the attendance dashboard),
      // while the rest of the row still opens the payslip detail drawer.
      // Stop bubble so the two handlers don't fight.
      onCell: (r) => ({
        onClick: (e) => {
          e.stopPropagation();
          onOpenAttendance?.(r);
        },
        style: onOpenAttendance ? { cursor: 'pointer' } : undefined,
      }),
    },
    moneyColumn<PayslipWithEmployee>({
      title: 'Gross',
      key: 'gross',
      dataIndex: (r) => r.salary?.grossSalary,
    }),
    moneyColumn<PayslipWithEmployee>({
      title: 'Deductions',
      key: 'deductions',
      dataIndex: (r) => r.salary?.totalDeduction,
    }),
    moneyColumn<PayslipWithEmployee>({
      title: 'Tax',
      key: 'tax',
      dataIndex: (r) => r.salary?.tax,
    }),
    moneyColumn<PayslipWithEmployee>({
      title: 'EOBI',
      key: 'eobi',
      dataIndex: (r) => r.salary?.eobi,
    }),
    {
      title: 'Net',
      key: 'net',
      align: 'right',
      render: (_v, row) =>
        row.salary?.netSalary == null ? (
          '—'
        ) : (
          <MoneyCell amount={row.salary.netSalary} style={{ fontWeight: 600 }} />
        ),
    },
    {
      title: 'Status',
      dataIndex: 'status',
      key: 'status',
      render: (s: PayslipStatus) => (
        <StatusPill tone={PAYSLIP_STATUS_TONE[s]}>{PAYSLIP_STATUS_LABEL[s]}</StatusPill>
      ),
    },
    {
      title: '',
      key: 'actions',
      width: 360,
      // Stop bubbling so PDF / hold / unhold / release clicks don't also
      // trip the row-level "open detail" handler below.
      onCell: () => ({ onClick: (e) => e.stopPropagation() }),
      render: (_v, row) => (
        <Space size={4} wrap>
          <Tooltip title={canViewPdf ? undefined : 'Available after posting'}>
            <Button
              size="small"
              icon={<FileText size={12} strokeWidth={1.75} />}
              disabled={!canViewPdf}
              loading={pdfPendingId === row.id}
              onClick={() => void viewPdf(row.id)}
            >
              View PDF
            </Button>
          </Tooltip>
          <PayslipRowActions
            runId={runId}
            payslipId={row.id}
            payslipStatus={row.status}
            runStatus={runStatus}
            onChanged={onRefresh}
          />
        </Space>
      ),
    },
  ];

  return (
    <Table<PayslipWithEmployee>
      rowKey="id"
      loading={loading}
      dataSource={payslips}
      columns={columns}
      onRow={
        onOpenDetail
          ? (r) => ({
              onClick: () => onOpenDetail(r.id),
              style: { cursor: 'pointer' },
            })
          : undefined
      }
      pagination={{
        current: page + 1,
        pageSize,
        total: totalElements,
        showSizeChanger: true,
        pageSizeOptions: [20, 50, 100, 200],
        showTotal: (t, [from, to]) => `${from}–${to} of ${t}`,
        onChange: (next, nextSize) => onPageChange(next - 1, nextSize),
      }}
      locale={{
        emptyText: (
          <Empty
            description={
              runStatus === 'COMPUTING'
                ? 'Computing payslips…'
                : 'No payslips matched the filter.'
            }
          />
        ),
      }}
      scroll={{ x: 900 }}
    />
  );
}
